package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import java.util.*;import java.math.BigInteger;import java.time.LocalDateTime;import javax.sql.DataSource;import org.springframework.jdbc.core.*;import org.springframework.test.util.ReflectionTestUtils;import org.junit.jupiter.api.*;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
/** Actual lifecycle and original Journal; explicit SQL/current permission fixtures, no deployed DB claim. */
class PublicationLifecycleTest {
 FormalAgentPublicationObjectLedgerTest f;FormalAgentPublicationLifecycle service;JdbcTemplate db;FormalAgentPublicationLifecycle.State state;FormalAgentPublicationLifecycle.Disabled disabled;JsonNode registration,request;String scopeStatus="ACTIVE";BigInteger scopeRevision=BigInteger.ONE;LocalDateTime scopeTime;boolean missingScope=false;
 @BeforeEach void setup()throws Exception{f=new FormalAgentPublicationObjectLedgerTest();f.begin();f.ledger.prepare(f.a,f.key,f.request,f.proof);f.now=f.now.plusSeconds(1);scopeTime=f.now;state=new FormalAgentPublicationLifecycle.State("PUBLISHED",BigInteger.TWO,f.proof.manifest().manifest().evaluationId(),f.now);registration=f.json.object().put("created_at",f.now.toString());((com.fasterxml.jackson.databind.node.ObjectNode)registration).putArray("scope_revisions").addObject().put("scope_revision",f.id(70)).put("scope_sha256",f.H);request=f.json.object().put("schema_version","1.0.0").put("release_id",f.row.release()).put("expected_revision","2").put("reason","Disable this exact release");service=new FormalAgentPublicationLifecycle(mock(DataSource.class),f.journal,f.guarded,f.resources,f.formal,f.json);db=mock(JdbcTemplate.class);ReflectionTestUtils.setField(service,"db",db);
 when(db.query(anyString(),any(RowMapper.class),any(Object[].class))).thenAnswer(i->{String sql=i.getArgument(0);Object[]v=PublicationRegistrationTest.args(i);if(sql.contains("FROM agent_version"))return List.of(state);if(sql.contains("FROM formal_agent_publication_disable"))return disabled==null?List.of():List.of(disabled);if(sql.contains("FROM release_scope"))return List.of(!missingScope&&scopeStatus.equals(v[3])&&scopeRevision.equals(v[4])&&scopeTime.equals(v[5])?1:0);throw new AssertionError(sql);});
 when(db.update(anyString(),any(Object[].class))).thenAnswer(i->{String sql=i.getArgument(0);Object[]v=PublicationRegistrationTest.args(i);if(sql.startsWith("INSERT INTO formal_agent_publication_disable")){disabled=new FormalAgentPublicationLifecycle.Disabled((String)v[1],(String)v[3],(String)v[4],(String)v[6],(LocalDateTime)v[7],"1.0.0",(String)v[5],(String)v[8]);return 1;}if(sql.startsWith("UPDATE agent_version")){state=new FormalAgentPublicationLifecycle.State("DISABLED",BigInteger.valueOf(3),state.evaluation(),(LocalDateTime)v[0]);return 1;}if(sql.startsWith("UPDATE release_scope")){scopeStatus="DISABLED";scopeRevision=BigInteger.TWO;scopeTime=(LocalDateTime)v[0];return 1;}throw new AssertionError(sql);});}
 @AfterEach void cleanup(){f.end();}
 void disable()throws Exception{f.now=f.now.plusSeconds(1);service.disable(f.a,"original-disable-key-001",request,f.row,registration);}
 @Test void publishedAndDisabledStatesVerifyOriginalJournal()throws Exception{service.requireState(f.a,f.row,registration);disable();service.requireState(f.a,f.row,registration);assertEquals("DISABLED",state.status());}
 @Test void wrongSidecarProjectFails()throws Exception{disable();disabled=new FormalAgentPublicationLifecycle.Disabled(f.id(99),disabled.decision(),disabled.hash(),disabled.creator(),disabled.created(),disabled.schemaVersion(),disabled.schemaManifest(),disabled.classification());assertThrows(TenantAccessException.class,()->service.requireState(f.a,f.row,registration));}
 @Test void changedHeadRevisionFails()throws Exception{state=new FormalAgentPublicationLifecycle.State(state.status(),BigInteger.valueOf(9),state.evaluation(),state.changed());assertThrows(TenantAccessException.class,()->service.requireState(f.a,f.row,registration));}
 @Test void missingScopeFails()throws Exception{missingScope=true;assertThrows(TenantAccessException.class,()->service.requireState(f.a,f.row,registration));}
 @Test void disabledScopeWithoutDecisionFails()throws Exception{scopeStatus="DISABLED";assertThrows(TenantAccessException.class,()->service.requireState(f.a,f.row,registration));}
 @Test void deletedOriginalAuditFails()throws Exception{disable();f.audits.clear();assertThrows(TenantAccessException.class,()->service.requireState(f.a,f.row,registration));}
 @Test void revokedWriteCannotCreateDisable()throws Exception{f.revoked=true;assertThrows(TenantAccessException.class,()->disable());assertNull(disabled);}
 @Test void originalReplayNeedsNoNewWriteGrant()throws Exception{disable();f.revoked=true;service.disable(f.a,"original-disable-key-001",request,f.row,registration);assertEquals(1,f.records.size());}
}
